#!/bin/bash
# This file was generated by Cursor AI on 2026-10-15.
# Install rIC3 (https://github.com/gipsyh/rIC3) and copy the ric3 binary into deps/.
# Direct AIGER/BTOR checking does not need Yosys. Bitwuzla is only required by the
# wlbmc engine; without a system Bitwuzla, that engine is stubbed and the build still succeeds.
source "$(dirname $0)/setup-utils.sh"

if ! command -v cargo >/dev/null 2>&1; then
    curl --proto '=https' --tlsv1.2 -sSf https://sh.rustup.rs | sh -s -- -y --profile minimal
    # shellcheck disable=SC1091
    source "$HOME/.cargo/env"
fi

if ! command -v cargo >/dev/null 2>&1; then
    echo "Failed installing the Rust toolchain (cargo not found)"
    exit 1
fi

pushd $DEPS_DIR
git clone --recurse-submodules https://github.com/gipsyh/rIC3.git
pushd rIC3
cargo build --release

if [[ $? -ne 0 ]]; then
    echo "Failed building rIC3"
    echo "rIC3 requires a Rust toolchain that supports edition 2024 (stable via rustup)."
    exit 1
fi

cp target/release/ric3 ../
popd
popd
